const int conversion_table[8] = { 0, 1, 2, 3, 5, 7, 8, 9 };



long long int octal_to_decimal(int octal_number){

	long long int decimal_number=0;

	for(int i=1 ; octal_number >0; i *= 10 , octal_number /= 8)

		decimal_number += (long long int)conversion_table[octal_number%8]*i;

	return decimal_number;

}

